Tactic Notation "scr_keep_hi" hyp(Hc) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) constr(HH) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells bsegs m' A cs)
        by (eapply (rw_cells_transport_scr_hi _ HH _ _ X XS m m' A cs RF);
            [ tac | exact Hc | exact MU | exact WM | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  | stk _ _ ?l ?h =>
      let N := fresh "KEEP" in
      assert (N : stk bsegs m' l h)
        by (eapply (stk_transport_scr _ HH _ _ X XS m m' l h RF);
            [ tac | exact Hc | exact MU | exact WM | cbn [disjoint_from fst snd]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.
Tactic Notation "scr_keep" hyp(Hc) "as" constr(OB) "over" hyp(MU) hyp(WM) hyp(RF) hyp(FS) constr(HH) "by" tactic3(tac) :=
  lazymatch type of MU with munch (?X ++ ?XS) ?m ?m' =>
  lazymatch type of Hc with
  | rw_cells _ _ ?A ?cs =>
      let N := fresh "KEEP" in
      assert (N : rw_cells bsegs m' A cs)
        by (eapply (rw_cells_transport_scr _ HH _ _ X XS m m' A cs RF);
            [ exact (proj1 OB) | exact (proj2 OB) | exact Hc | exact MU | exact WM
            | fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac | exact FS ]);
      clear Hc; rename N into Hc
  | bytes_at _ _ ?A ?bs =>
      let N := fresh "KEEP" in
      assert (N : bytes_at bsegs m' A bs)
        by (eapply (bytes_at_transport_scr _ HH _ _ X XS m m' A bs RF);
            [ intros _; exact OB | exact Hc | exact MU | cbn [disjoint_from fst snd]; tac | exact FS ]);
      clear Hc; rename N into Hc
  end end.

