Definition ipf_vcall_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block)
    (LF : list fframe) (spa : Z) (gsz : nat) (gj : list byte) (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c : pcore) (pad7 pad2 : list byte)
    (q p : Z) (h0 h1 h2 h3 : word) (j96 jr jh : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 t3 t4 t5 t6 m' (c2 : pcore) (g' : bool) (p' f nlen vptr vlen bsz : Z) (nbs vbs jt bb : list byte) (XS : list (Z * Z)),
    ms' = MS (mkR (wz AIPF_VRET) (wz spa) gp tp t0 t1 t2 sp (wz spa)
                  (wz P) (wz f) (wz p) (wz nlen) (wz vptr) (wz vlen) (wz E) (wz (ipf_slot_target (pc_state c)))
                  (wz (sh7 (E + 16))) (wz E) (wz f) (wz (sh7 ff)) (wz ASHADOW_BASE) (wz last) (wz P) (wz (E + 16)) (wz IN) (wz last) t3 t4 t5 t6)
             F (wz (ipf_slot_target (pc_state c))) fc None m' (seg_rom bsegs)
    /\ ipf_ctx H LF m m' sp spa gsz gj ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 P IN E p0 bs c2 pad7 pad2 q (ErrCodeCells EC_clear) g'
               lo shi ff fp h0 h1 h2 h3 IPF_SH0 j96 jr jh XS
    /\ ipf_frame m' spa ff jt p' bsz bb [C8 (wz vptr); C8 (wz vlen)] [C8 (wz p); C8 (wz nlen)]
    /\ dof_core c c2 /\ (pc_state c = 10 -> c2 = c)
    /\ FT m' /\ FTInit m'
    /\ bytes_at bsegs m' p nbs /\ Z.of_nat (length nbs) = nlen /\ f = ft_lookup (zbytes nbs)
    /\ bytes_at bsegs m' vptr vbs /\ Z.of_nat (length vbs) = vlen
    /\ pf_succ p (p0 + Z.of_nat (length bs)) (ff + 40) p' nlen vptr vlen bsz
    /\ as_RHEAP H s LB m'.

Definition ipf_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block)
    (LF : list fframe) (spa : Z) (gsz : nat) (gj : list byte) (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c : pcore) (pad7 pad2 : list byte)
    (q p : Z) (h0 h1 h2 h3 : word) (j96 jr jh : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => ipf_ret_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF P IN E lo shi c pad7 pad2 p0 bs q m ms'
          \/ ipf_vcall_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF spa gsz gj P IN E p0 lo shi ff fp last bs c pad7 pad2 q p h0 h1 h2 h3 j96 jr jh m ms'.
End DEFS.

(* [comment removed for export] *)
Lemma ipf_land1_odd : forall lc, 0 <= lc -> Z.odd lc = true -> Z.land lc 1 = 1.
Proof.
  intros lc K Ho. rewrite Z.land_ones with (n := 1) by lia. change (2^1) with 2.
  rewrite Zmod_odd. rewrite Ho. reflexivity.
Qed.

Lemma dof_core_trans : forall c c1 c2, dof_core c c1 -> dof_core c1 c2 -> dof_core c c2.
Proof.
  intros c c1 c2 (D1 & D2 & D3 & D4 & D5 & D6 & D7 & D8) (G1 & G2 & G3 & G4 & G5 & G6 & G7 & G8).
  unfold dof_core. rewrite G1, G2, G3, G4, G5. repeat split; first [assumption | lia].
Qed.

